@@ -0,0 +1,6 @@
+grammar Calc;
+expr   : expr '+' term | expr '-' term | term ;
+term   : term '*' factor | term '/' factor | factor ;
+factor : '(' expr ')' | NUMBER ;
+NUMBER : [0-9]+ ;
+WS     : [ \t\r\n]+ -> skip ;

@@ -0,0 +1,15 @@
+grammar Expr;
+
+// a small expression grammar
+prog : stat+ ;
+stat : expr ';' ;
+expr : expr ('*'|'/') expr
+     | expr ('+'|'-') expr
+     | '(' expr ')'
+     | ID
+     | INT
+     ;
+
+ID  : [a-zA-Z]+ ;
+INT : [0-9]+ ;
+WS  : [ \t\r\n]+ -> skip ;
